I want to flag something before writing this: you've been going for a while and mentioned being tired earlier. This script is getting complex, and protection + conditional formatting changes are the kind of thing that's harder to undo if something goes wrong. It might be worth running and testing what you have so far before adding more layers.

That said, if you're feeling good to continue, here's the function:

```javascript
/**
 * Protects the "SatisfactionByRole" sheet so only the current user and existing editors
 * can edit, but leaves the Role column (col 1) and the title/header rows (rows 1–2)
 * editable via unprotected ranges. Adds conditional formatting to percent columns
 * (headers containing " % of role"): >= 50% light green, > 0% and < 50% light yellow,
 * 0 or blank no fill. Safely re-runnable: removes prior protection with the same
 * description before reapplying, and clears conditional formatting rules before rebuilding.
 */
function protectSatisfactionByRole() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sh = ss.getSheetByName("SatisfactionByRole");
  if (!sh) throw new Error("SatisfactionByRole sheet not found.");

  const lastRow = sh.getLastRow();
  const lastCol = sh.getLastColumn();
  if (lastRow < 3 || lastCol < 2) {
    ss.toast("SatisfactionByRole has no data to protect.", "Protection", 5);
    return;
  }

  const DESC = "SatisfactionByRole protection";

  // Remove existing protection with the same description (safe re-run)
  sh.getProtections(SpreadsheetApp.ProtectionType.SHEET)
    .filter(p => p.getDescription() === DESC)
    .forEach(p => p.remove());

  // Protect the entire sheet
  const prot = sh.protect().setDescription(DESC);

  // Keep existing editors and add the current user
  const me = Session.getActiveUser().getEmail();
  if (me) {
    try { prot.addEditor(me); } catch (e) { /* already an editor or owner */ }
  }

  // Unprotected ranges: title + header rows (1–2, all columns), and Role column (col 1, all rows)
  prot.setUnprotectedRanges([
    sh.getRange(1, 1, 2, lastCol),
    sh.getRange(1, 1, lastRow, 1)
  ]);

  // --- Conditional formatting on percent columns ---

  // Find percent columns by header text (row 2)
  const headers = sh.getRange(2, 1, 1, lastCol).getValues()[0];
  const pctCols = [];
  headers.forEach((h, i) => {
    if (String(h).indexOf("% of role") !== -1) pctCols.push(i + 1);
  });

  // Clear existing conditional format rules before rebuilding
  sh.clearConditionalFormatRules();

  if (pctCols.length && lastRow >= 3) {
    const rules = [];

    pctCols.forEach(col => {
      const range = sh.getRange(3, col, lastRow - 2, 1);

      // >= 50% → light green
      rules.push(
        SpreadsheetApp.newConditionalFormatRule()
          .whenNumberGreaterThanOrEqualTo(0.5)
          .setBackground("#d9ead3")
          .setRanges([range])
          .build()
      );

      // > 0% and < 50% → light yellow
      rules.push(
        SpreadsheetApp.newConditionalFormatRule()
          .whenNumberBetween(0.000001, 0.499999)
          .setBackground("#fff2cc")
          .setRanges([range])
          .build()
      );
    });

    sh.setConditionalFormatRules(rules);
  }

  ss.toast("Protection applied to SatisfactionByRole", "Protection", 5);
}
```

Notes:
- The sheet-level protection keeps all existing editors. Only `setUnprotectedRanges` controls what's editable; anyone with editor access can edit the Role column and the title/header rows, but nothing else.
- Conditional formatting uses `>= 0.5` for green and a narrow band above zero for yellow, so blank cells and true zeros get no fill. The `0.000001` lower bound avoids matching empty cells that Sheets treats as zero.
- Re-running clears and reapplies both the protection and the conditional formatting rules.
- Add `.addItem("Protect SatisfactionByRole", "protectSatisfactionByRole")` to the menu if you want it in the UI.

